import { prisma } from "@/lib/prisma";
import { ensureSovereignAsset } from "@/lib/asset-pipeline";
import { revalidateTag } from "next/cache";

export type SyncAssetsOptions = {
  owner: string;
  repo: string;
  token: string;
  branch?: string;
  projectId?: string;
};

export type SyncAssetsResult = {
  success: boolean;
  projectId: string;
  syncedAssets: string[];
  coverImageSet: boolean;
  previewGifSet: boolean;
  message: string;
};

/**
 * Fetches binary file buffer from GitHub via raw contents endpoint
 */
async function fetchGitHubAssetBuffer(
  owner: string,
  repo: string,
  filePath: string,
  branch: string,
  token: string
): Promise<{ buffer: Buffer; filename: string; contentType: string } | null> {
  try {
    // 1. Try raw content via GitHub API headers
    const rawRes = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${encodeURIComponent(branch)}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github.v3.raw",
        },
      }
    );

    if (rawRes.ok) {
      const arrayBuffer = await rawRes.arrayBuffer();
      if (arrayBuffer.byteLength > 100) {
        const ext = filePath.split(".").pop()?.toLowerCase();
        const contentType = ext === "gif" ? "image/gif" : ext === "webp" ? "image/webp" : "image/png";
        return {
          buffer: Buffer.from(arrayBuffer),
          filename: filePath.split("/").pop() || "asset",
          contentType,
        };
      }
    }

    // 2. Fallback to standard contents API metadata (which provides download_url or base64)
    const jsonRes = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${encodeURIComponent(branch)}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github+json",
        },
      }
    );

    if (!jsonRes.ok) return null;

    const data = await jsonRes.json();
    const ext = filePath.split(".").pop()?.toLowerCase();
    const contentType = ext === "gif" ? "image/gif" : ext === "webp" ? "image/webp" : "image/png";

    if (data.download_url) {
      const dlRes = await fetch(data.download_url);
      if (dlRes.ok) {
        const buf = await dlRes.arrayBuffer();
        return {
          buffer: Buffer.from(buf),
          filename: data.name || filePath.split("/").pop() || "asset",
          contentType,
        };
      }
    }

    if (data.content && data.encoding === "base64") {
      return {
        buffer: Buffer.from(data.content, "base64"),
        filename: data.name || filePath.split("/").pop() || "asset",
        contentType,
      };
    }
  } catch (err) {
    console.warn(`[Sync Assets] Warning fetching ${filePath}:`, err);
  }

  return null;
}

/**
 * Syncs generated repository visual assets (hero.png, fullpage.png, mobile.png, preview.gif)
 * directly into Supabase Storage and updates the database Project coverImageUrl.
 */
export async function syncRepoAssetsToProject(
  options: SyncAssetsOptions
): Promise<SyncAssetsResult> {
  const { owner, repo, token, branch = "main", projectId: explicitProjectId } = options;
  const fullName = `${owner}/${repo}`;

  // 1. Resolve PostgreSQL database project document
  const cleanId = explicitProjectId?.replace(/^drafts\./, "");
  const dbProject = await prisma.project.findFirst({
    where: {
      OR: [
        ...(cleanId ? [{ id: cleanId }, { slug: cleanId }] : []),
        { githubUrl: { contains: fullName, mode: "insensitive" } },
        { githubUrl: { contains: repo, mode: "insensitive" } },
        { slug: repo.toLowerCase() },
      ],
    },
  });

  if (!dbProject) {
    throw new Error(
      `No matching database project found for repository "${fullName}". Import the project into Lab first.`
    );
  }

  const syncedAssets: string[] = [];
  let sovereignCoverUrl: string | null = null;
  let previewGifUrl: string | null = null;

  // 2. Define target visual assets generated by GitHub Actions
  const targetFiles = [
    { path: "assets/hero.png", caption: "Desktop Hero View", isCoverCandidate: true },
    { path: "assets/fullpage.png", caption: "Fullpage Scrolling Architecture", isCoverCandidate: false },
    { path: "assets/mobile.png", caption: "Mobile Responsive Layout", isCoverCandidate: false },
  ];

  // 3. Download and ingest screenshots to Supabase Storage
  for (const item of targetFiles) {
    const assetData = await fetchGitHubAssetBuffer(owner, repo, item.path, branch, token);
    if (assetData) {
      console.log(`[Sync Assets] Ingesting ${item.path} (${assetData.buffer.length} bytes) to Supabase Storage...`);
      const dataUrl = `data:${assetData.contentType};base64,${assetData.buffer.toString("base64")}`;
      const uploadedUrl = await ensureSovereignAsset(dataUrl, {
        folder: "captures",
        contentType: assetData.contentType,
        customFileName: `${repo}-${item.path.replace(/[/.]/g, "-")}-${Date.now().toString(36)}.png`,
      });

      if (uploadedUrl) {
        syncedAssets.push(item.path);
        if (item.isCoverCandidate && !sovereignCoverUrl) {
          sovereignCoverUrl = uploadedUrl;
        }
      }
    }
  }

  // 4. Look for animated preview GIF
  const gifCandidates = ["assets/preview.gif", "assets/preview-desktop.gif", "assets/mobile.gif"];
  for (const gifPath of gifCandidates) {
    const gifData = await fetchGitHubAssetBuffer(owner, repo, gifPath, branch, token);
    if (gifData) {
      console.log(`[Sync Assets] Ingesting ${gifPath} to Supabase Storage...`);
      const dataUrl = `data:image/gif;base64,${gifData.buffer.toString("base64")}`;
      const uploadedGif = await ensureSovereignAsset(dataUrl, {
        folder: "captures",
        contentType: "image/gif",
        customFileName: `${repo}-preview-${Date.now().toString(36)}.gif`,
      });

      if (uploadedGif) {
        previewGifUrl = uploadedGif;
        syncedAssets.push(gifPath);
        break;
      }
    }
  }

  // 5. Update Project in PostgreSQL via Prisma
  let coverImageSet = false;
  let previewGifSet = Boolean(previewGifUrl);

  const updateData: { coverImageUrl?: string; assetSource?: string } = {};
  if (sovereignCoverUrl) {
    updateData.coverImageUrl = sovereignCoverUrl;
    updateData.assetSource = "GITHUB_ACTION_CAPTURE";
    coverImageSet = true;
  } else if (!dbProject.coverImageUrl && previewGifUrl) {
    updateData.coverImageUrl = previewGifUrl;
    updateData.assetSource = "GITHUB_ACTION_CAPTURE";
    coverImageSet = true;
  }

  if (Object.keys(updateData).length > 0) {
    await prisma.project.update({
      where: { id: dbProject.id },
      data: updateData,
    });

    try {
      revalidateTag("projects", "max");
      revalidateTag(`project:${dbProject.id}`, "max");
      revalidateTag(`project:${dbProject.slug}`, "max");
    } catch {}
  }

  console.log(`[Sync Assets] Successfully synced assets to Supabase Storage for project ${dbProject.slug}!`);

  return {
    success: true,
    projectId: dbProject.id,
    syncedAssets,
    coverImageSet,
    previewGifSet,
    message: syncedAssets.length > 0
      ? `Successfully ingested ${syncedAssets.length} visual asset(s) to Supabase Storage & updated database!`
      : "No new visual assets found in repository assets/ directory. Run visual capture first.",
  };
}
